import{_ as a,o as i,c as t,a8 as n}from"./chunks/framework.BG9kL4Xs.js";const g=JSON.parse('{"title":"User docs","description":"","frontmatter":{},"headers":[],"relativePath":"content/plugins/bcew-blocks/user-docs.md","filePath":"content/plugins/bcew-blocks/user-docs.md"}'),s={name:"content/plugins/bcew-blocks/user-docs.md"};function o(l,e,r,c,d,h){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="user-docs" tabindex="-1">User docs <a class="header-anchor" href="#user-docs" aria-label="Permalink to “User docs”">​</a></h1><p>This guide explains how content authors insert and configure blocks provided by <code>bcew-blocks</code>.</p><h2 id="before-you-begin" tabindex="-1">Before you begin <a class="header-anchor" href="#before-you-begin" aria-label="Permalink to “Before you begin”">​</a></h2><ul><li>The <code>bcew-blocks</code> plugin is installed and activated in WordPress.</li></ul><h2 id="add-a-block" tabindex="-1">Add a block <a class="header-anchor" href="#add-a-block" aria-label="Permalink to “Add a block”">​</a></h2><ol><li>In the editor, insert blocks using the block inserter and search for the block name.</li><li>Configure block settings in the sidebar.</li><li>Publish or update the page.</li></ol><h2 id="icon" tabindex="-1">Icon <a class="header-anchor" href="#icon" aria-label="Permalink to “Icon”">​</a></h2><p>Displays a single icon with configurable size and accessibility labeling.</p><ul><li>Category: Media</li><li>Intended use: visual icon element in content layouts</li></ul><h3 id="icon-settings" tabindex="-1">Icon settings <a class="header-anchor" href="#icon-settings" aria-label="Permalink to “Icon settings”">​</a></h3><ul><li><strong>Pick an icon</strong>: selects the icon to display.</li><li><strong>Icon size</strong>: display size (Small, Medium, Large, or XLarge). Default is Medium.</li><li><strong>Decorative</strong>: whether assistive technology should ignore the icon. Off by default.</li><li><strong>Accessible name</strong>: accessible text label when the icon is not decorative.</li></ul><h3 id="accessibility" tabindex="-1">Accessibility <a class="header-anchor" href="#accessibility" aria-label="Permalink to “Accessibility”">​</a></h3><ul><li>When <strong>Decorative</strong> is on, the icon does not require an accessible name.</li><li>When <strong>Decorative</strong> is off, provide a meaningful <strong>Accessible name</strong>.</li></ul><h2 id="media-text-layout" tabindex="-1">Media &amp; Text Layout <a class="header-anchor" href="#media-text-layout" aria-label="Permalink to “Media &amp; Text Layout”">​</a></h2><p>Presents media and text side-by-side with configurable image placement.</p><ul><li>Category: Media</li><li>Intended use: paired media and narrative content sections</li></ul><h3 id="media-text-layout-settings" tabindex="-1">Media &amp; Text Layout settings <a class="header-anchor" href="#media-text-layout-settings" aria-label="Permalink to “Media &amp; Text Layout settings”">​</a></h3><ul><li>Image: select an image from the media library.</li><li><strong>Image on right</strong>: places the image to the right of the text. By default, the image is on the left.</li></ul><h3 id="authoring-guidance" tabindex="-1">Authoring guidance <a class="header-anchor" href="#authoring-guidance" aria-label="Permalink to “Authoring guidance”">​</a></h3><ul><li>Keep text concise when media is the primary focus.</li><li>Use image placement to support reading flow and hierarchy.</li></ul>',20)])])}const b=a(s,[["render",o]]);export{g as __pageData,b as default};
